/* touch_select.js */
try {
// Touch devices: no row checkboxes. A long press on a row starts selection, then taps toggle rows until
// the selection is cleared. It drives the existing .row-select checkboxes, so bulk_select.js and
// tasks_table.js keep owning the selection, the bar and the actions. Feature notes: features/mobile-touch.md.
(function () {
  var HOLD_MS = 450;
  var MOVE_PX = 10;
  var ROW = "tr, .contact-row-wrap";
  var timer = null;
  var start = null;
  var justSelected = false;
  var toggling = false;

  function rowCheckbox(target) {
    var row = target.closest && target.closest(ROW);
    return row ? row.querySelector(".row-select") : null;
  }

  function toggle(cb) {
    toggling = true;
    cb.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, pointerType: "mouse" }));
    cb.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    document.dispatchEvent(new PointerEvent("pointerup", { bubbles: true }));
    toggling = false;
  }

  function sync() {
    document.body.classList.toggle("touch-selecting", !!document.querySelector(".row-select:checked"));
  }

  function cancel() {
    clearTimeout(timer);
    timer = null;
    start = null;
  }

  document.addEventListener("pointerdown", function (e) {
    if (e.pointerType !== "touch" || e.target.closest(".bulk-actions-bar")) return;
    var cb = rowCheckbox(e.target);
    if (!cb) return;
    start = { x: e.clientX, y: e.clientY };
    timer = setTimeout(function () {
      timer = null;
      if (!cb.checked) toggle(cb);
      justSelected = true;
      if (navigator.vibrate) navigator.vibrate(10);
      sync();
    }, HOLD_MS);
  });

  document.addEventListener("pointermove", function (e) {
    if (start && Math.hypot(e.clientX - start.x, e.clientY - start.y) > MOVE_PX) cancel();
  });
  ["pointerup", "pointercancel", "scroll"].forEach(function (name) {
    document.addEventListener(name, cancel, true);
  });

  // The press that started a selection must not also open the row; later taps toggle while selecting.
  document.addEventListener("click", function (e) {
    if (toggling) return;
    if (e.target.closest(".bulk-actions-bar")) {
      setTimeout(sync, 0);
      return;
    }
    if (justSelected) {
      justSelected = false;
      e.preventDefault();
      e.stopPropagation();
      return;
    }
    if (!document.body.classList.contains("touch-selecting")) return;
    var cb = rowCheckbox(e.target);
    if (!cb) return;
    e.preventDefault();
    e.stopPropagation();
    toggle(cb);
    sync();
  }, true);

  document.addEventListener("contextmenu", function (e) {
    if (e.pointerType === "touch" && rowCheckbox(e.target)) e.preventDefault();
  });
})();

} catch (err) { console.error('touch_select.js', err); }
/* select_all.js */
try {
// Header checkbox of a table: selects or clears every visible row checkbox by driving them the way a click does,
// so bulk_select.js and tasks_table.js keep owning the selection and the bulk bar.
(function () {
  function rowBoxes(all) {
    const scope = all.closest("table") || document;
    return Array.from(scope.querySelectorAll("tbody .row-select")).filter((cb) => cb.offsetParent !== null);
  }

  function toggle(cb) {
    cb.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true, pointerType: "mouse" }));
    cb.dispatchEvent(new MouseEvent("click", { bubbles: true, cancelable: true }));
    document.dispatchEvent(new PointerEvent("pointerup", { bubbles: true }));
  }

  function sync() {
    document.querySelectorAll(".select-all").forEach((all) => {
      const boxes = rowBoxes(all);
      const n = boxes.filter((cb) => cb.checked).length;
      all.checked = boxes.length > 0 && n === boxes.length;
      all.indeterminate = n > 0 && n < boxes.length;
    });
  }

  document.addEventListener("click", (e) => {
    const all = e.target.closest && e.target.closest(".select-all");
    if (all) {
      const on = all.checked;
      rowBoxes(all).forEach((cb) => {
        if (cb.checked !== on) toggle(cb);
      });
    }
    sync();
  });
  document.addEventListener("cc-region-refreshed", sync);
})();

} catch (err) { console.error('select_all.js', err); }
/* sidebar_tree.js */
try {
(function () {
  const EXPANDED_KEY = "commandCenterWeb.sidebarExpanded";
  const CHILD_KEY_PREFIX = "commandCenterWeb.sidebarTreeOpen."; // + space name

  function isExpanded() {
    return document.documentElement.hasAttribute("data-sidebar-expanded");
  }

  function setExpanded(expanded) {
    if (expanded) {
      document.documentElement.setAttribute("data-sidebar-expanded", "1");
      localStorage.setItem(EXPANDED_KEY, "1");
    } else {
      document.documentElement.removeAttribute("data-sidebar-expanded");
      localStorage.removeItem(EXPANDED_KEY);
    }
    document.querySelectorAll("#sidebar-expand-toggle, [data-sidebar-toggle]").forEach((toggle) => {
      toggle.setAttribute("aria-pressed", expanded ? "true" : "false");
      toggle.title = expanded ? "Collapse sidebar" : "Expand sidebar";
      toggle.setAttribute("aria-label", toggle.title);
    });
    window.dispatchEvent(new Event("resize"));
    setTimeout(() => window.dispatchEvent(new Event("resize")), 180);
  }

  function initExpandToggle() {
    // Sync the buttons' own state with what the head script already
    // applied -- this file loads after that inline script has run.
    setExpanded(isExpanded());
    document.querySelectorAll("#sidebar-expand-toggle, [data-sidebar-toggle]").forEach((toggle) => {
      if (toggle.dataset.bound) return;
      toggle.dataset.bound = "1";
      toggle.addEventListener("click", () => setExpanded(!isExpanded()));
    });
  }

  // Per-space project-tree toggles. A space with no stored preference keeps
  // whatever the server rendered (open only when one of its own children is
  // the active page, see base.html) -- localStorage only overrides that
  // once the user has actually clicked a chevron for that space.
  function initTreeToggles() {
    document.querySelectorAll(".sidebar-tree-item.has-children").forEach((item) => {
      const toggleBtn = item.querySelector(".sidebar-tree-toggle");
      if (!toggleBtn || toggleBtn.dataset.bound) return;
      toggleBtn.dataset.bound = "1";
      const spaceName = item.dataset.spaceName || "";
      const stored = spaceName ? localStorage.getItem(CHILD_KEY_PREFIX + spaceName) : null;
      if (stored === "1") toggleBtn.setAttribute("aria-expanded", "true");
      else if (stored === "0") toggleBtn.setAttribute("aria-expanded", "false");
      // stored === null: no override, keep the server-rendered default.

      toggleBtn.addEventListener("click", () => {
        const nowOpen = toggleBtn.getAttribute("aria-expanded") !== "true";
        toggleBtn.setAttribute("aria-expanded", nowOpen ? "true" : "false");
        if (spaceName) localStorage.setItem(CHILD_KEY_PREFIX + spaceName, nowOpen ? "1" : "0");
      });
    });
  }

  function init() {
    initExpandToggle();
    initTreeToggles();
  }

  document.addEventListener("DOMContentLoaded", init);
  // Cross-document view transitions (see base.html's no-cdt note) can
  // re-run without a fresh DOMContentLoaded on some navigations -- the
  // dataset.bound guards above make re-running init() harmless/idempotent.
  document.addEventListener("pagereveal", init);
})();

} catch (err) { console.error('sidebar_tree.js', err); }
